package main

import (
	"fmt"
)

func main() {
	var myarray string
	fmt.Scan(&myarray)
	cnt := 0
	len := len(myarray)
	for i := 0; i < len; i++ {
		if myarray[i] == 'Q' {
			for j := i + 1; j < len; j++ {
				if myarray[j] == 'A' {
					for l := j + 1; l < len; l++ {
						if myarray[l] == 'Q' {
							cnt++
						}
					}
				}
			}
		}
	}
	fmt.Print(cnt)
}

